from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal("0.01")
_FOUR = Decimal("0.0001")
_TYPES = {"PURCHASE", "SALE", "CUSTOMER_RETURN", "PURCHASE_RETURN"}


def _quantize_prec(value, target_exp):
    tup = value.as_tuple()
    ld = len(tup.digits)
    e = tup.exponent
    # e is int for finite values (all quantized values are finite)
    extra = 0
    if isinstance(e, int) and e > target_exp:
        extra = e - target_exp
    return max(28, ld + extra + 10)


def _d2(value):
    with localcontext() as ctx:
        ctx.prec = _quantize_prec(value, -2)
        return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def _q4(value):
    with localcontext() as ctx:
        ctx.prec = _quantize_prec(value, -4)
        return value.quantize(_FOUR, rounding=ROUND_HALF_UP)


def _mul_int_exact(d, n):
    with localcontext() as ctx:
        ctx.prec = max(28, len(d.as_tuple().digits) + len(str(abs(n))) + 10)
        return d * n


def _add_sub_prec(a, b):
    ta = a.as_tuple()
    tb = b.as_tuple()
    la = len(ta.digits)
    lb = len(tb.digits)
    ea = ta.exponent
    eb = tb.exponent
    # All values here are finite with int exponents.
    emin = ea if ea < eb else eb
    need = la + (ea - emin)
    other = lb + (eb - emin)
    if other > need:
        need = other
    return max(28, need + 10)


def _add_exact(a, b):
    with localcontext() as ctx:
        ctx.prec = _add_sub_prec(a, b)
        return a + b


def _sub_exact(a, b):
    with localcontext() as ctx:
        ctx.prec = _add_sub_prec(a, b)
        return a - b


def _div50(a, b):
    with localcontext() as ctx:
        ctx.prec = 50
        return a / Decimal(b)


def process_inventory(movements: list[dict]) -> dict:
    if not isinstance(movements, list):
        raise ValueError("movements must be a list")
    qty = 0
    value = Decimal("0.00")
    total_cogs = Decimal("0.00")
    total_pr = Decimal("0.00")
    for mv in movements:
        if not isinstance(mv, dict):
            raise ValueError("movement must be a dict")
        mtype = mv.get("type")
        if not isinstance(mtype, str) or mtype not in _TYPES:
            raise ValueError(f"invalid movement type: {mtype!r}")
        quantity = mv.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive int")
        if mtype == "PURCHASE":
            if "unit_cost" not in mv:
                raise ValueError("unit_cost required for PURCHASE")
            raw = mv["unit_cost"]
            if not isinstance(raw, str):
                raise ValueError("unit_cost must be a string")
            try:
                cost = Decimal(raw)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid unit_cost: {raw!r}") from None
            if not cost.is_finite() or cost < 0:
                raise ValueError("unit_cost must be finite and >= 0")
            added = _d2(_mul_int_exact(cost, quantity))
            value = _d2(_add_exact(value, added))
            qty += quantity
        elif mtype == "SALE":
            if quantity > qty:
                raise ValueError("sale exceeds quantity on hand")
            avg = _div50(value, qty)
            cogs = _d2(_mul_int_exact(avg, quantity))
            value = _d2(_sub_exact(value, cogs))
            qty -= quantity
            total_cogs = _d2(_add_exact(total_cogs, cogs))
        elif mtype == "CUSTOMER_RETURN":
            if qty == 0:
                raise ValueError("no current average cost for customer return")
            avg = _div50(value, qty)
            added = _d2(_mul_int_exact(avg, quantity))
            value = _d2(_add_exact(value, added))
            qty += quantity
        else:  # PURCHASE_RETURN
            if quantity > qty:
                raise ValueError("purchase return exceeds quantity on hand")
            avg = _div50(value, qty)
            removed = _d2(_mul_int_exact(avg, quantity))
            value = _d2(_sub_exact(value, removed))
            qty -= quantity
            total_pr = _d2(_add_exact(total_pr, removed))
    if qty == 0:
        avg_out = Decimal("0.0000")
    else:
        avg_out = _q4(_div50(value, qty))
    return {
        "quantity_on_hand": qty,
        "inventory_value": _d2(value),
        "average_cost": avg_out,
        "total_cogs": _d2(total_cogs),
        "total_purchase_returns": _d2(total_pr),
    }
